import math

def eps(q,z,t,alpha,delta=1e-9):
 vals=[]
 for i in range(alpha+1):
  lc=math.lgamma(alpha+1)-math.lgamma(i+1)-math.lgamma(alpha-i+1)
  vals.append(lc+i*math.log(q)+(alpha-i)*math.log1p(-q)+(i*i-i)/(2*z*z))
 m=max(vals)
 rdp=(m+math.log(sum(math.exp(v-m) for v in vals)))/(alpha-1)
 return t*rdp-(math.log(delta)+math.log(alpha))/(alpha-1)+math.log((alpha-1)/alpha)
